import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testWithDuplicates() {
        Assert.assertTrue(hasDuplicates(listOf(4215, 1234, 4215)))
    }

    @Test
    fun testWithoutDuplicates() {
        Assert.assertFalse(hasDuplicates(listOf(4215, 1234, 5678)))
    }

    @Test
    fun testEmptyList() {
        Assert.assertFalse(hasDuplicates(listOf()))
    }

    @Test
    fun testSingleElement() {
        Assert.assertFalse(hasDuplicates(listOf(4215)))
    }

    @Test
    fun testAllDuplicates() {
        Assert.assertTrue(hasDuplicates(listOf(4215, 4215, 4215)))
    }
}
